import hashlib
import hmac
import os
import sqlite3
import time
import secrets
import re
from functools import wraps
from flask import Flask, request, jsonify, g, abort

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
app.config['DATABASE'] = os.environ.get('DB_PATH', '/var/app/data/users.db')
app.config['MAX_LOGIN_ATTEMPTS'] = 5
app.config['LOCKOUT_DURATION'] = 900  # 15 minutes

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT DEFAULT 'user',
            created_at REAL DEFAULT (julianday('now')),
            is_active INTEGER DEFAULT 1
        );
        CREATE TABLE IF NOT EXISTS sessions (
            token TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            created_at REAL NOT NULL,
            expires_at REAL NOT NULL,
            ip_address TEXT,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS login_attempts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            ip_address TEXT NOT NULL,
            attempted_at REAL NOT NULL,
            success INTEGER DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            action TEXT NOT NULL,
            details TEXT,
            ip_address TEXT,
            performed_at REAL DEFAULT (julianday('now'))
        );
    ''')
    db.commit()

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8') if isinstance(a, str) else a,
                               b.encode('utf-8') if isinstance(b, str) else b)

def hash_password(password, salt=None):
    """Hash password using PBKDF2-HMAC-SHA256 with 100k iterations."""
    if salt is None:
        salt = secrets.token_hex(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'),
                              salt.encode('utf-8'), 100000)
    return f"{salt}${dk.hex()}"

def verify_password(password, stored_hash):
    """Verify password against stored hash."""
    try:
        salt, hash_value = stored_hash.split('$', 1)
        computed = hash_password(password, salt)
        return constant_time_compare(computed, stored_hash)
    except (ValueError, AttributeError):
        # Prevent timing oracle on malformed hashes
        hash_password(password, 'dummy_salt_value_1234')
        return False

def check_rate_limit(username, ip_address):
    """Check if login attempts exceed threshold."""
    db = get_db()
    cutoff = time.time() - app.config['LOCKOUT_DURATION']
    result = db.execute(
        'SELECT COUNT(*) as cnt FROM login_attempts '
        'WHERE (username = ? OR ip_address = ?) AND attempted_at > ? AND success = 0',
        (username, ip_address, cutoff)
    ).fetchone()
    return result['cnt'] < app.config['MAX_LOGIN_ATTEMPTS']

def record_attempt(username, ip_address, success):
    """Record a login attempt."""
    db = get_db()
    db.execute(
        'INSERT INTO login_attempts (username, ip_address, attempted_at, success) VALUES (?, ?, ?, ?)',
        (username, ip_address, time.time(), int(success))
    )
    db.commit()

def create_session(user_id, ip_address):
    """Create a new session token."""
    token = secrets.token_urlsafe(32)
    db = get_db()
    now = time.time()
    expires = now + 3600  # 1 hour
    db.execute(
        'INSERT INTO sessions (token, user_id, created_at, expires_at, ip_address) VALUES (?, ?, ?, ?, ?)',
        (token, user_id, now, expires, ip_address)
    )
    db.commit()
    return token

def validate_session(token):
    """Validate session token and return user info."""
    db = get_db()
    session = db.execute(
        'SELECT s.*, u.username, u.role, u.is_active FROM sessions s '
        'JOIN users u ON s.user_id = u.id WHERE s.token = ?',
        (token,)
    ).fetchone()
    if session is None:
        return None
    if session['expires_at'] < time.time():
        db.execute('DELETE FROM sessions WHERE token = ?', (token,))
        db.commit()
        return None
    if not session['is_active']:
        return None
    return dict(session)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401
        token = auth_header[7:]
        session = validate_session(token)
        if session is None:
            return jsonify({'error': 'Invalid or expired session'}), 401
        g.current_user = session
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user['role'] != role:
                return jsonify({'error': 'Insufficient permissions'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

def audit_log(user_id, action, details=None):
    """Record an audit log entry."""
    db = get_db()
    db.execute(
        'INSERT INTO audit_log (user_id, action, details, ip_address, performed_at) '
        'VALUES (?, ?, ?, ?, ?)',
        (user_id, action, details, request.remote_addr, time.time())
    )
    db.commit()

def validate_username(username):
    """Validate username format."""
    if not username or len(username) < 3 or len(username) > 32:
        return False
    return bool(re.match(r'^[a-zA-Z][a-zA-Z0-9_]+$', username))

def validate_password_strength(password):
    """Enforce password complexity requirements."""
    if len(password) < 12:
        return False, 'Password must be at least 12 characters'
    if not re.search(r'[A-Z]', password):
        return False, 'Password must contain uppercase letter'
    if not re.search(r'[a-z]', password):
        return False, 'Password must contain lowercase letter'
    if not re.search(r'[0-9]', password):
        return False, 'Password must contain a digit'
    return True, ''

@app.route('/api/auth/login', methods=['POST'])
def login():
    """Authenticate user and return session token."""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    username = data.get('username', '').strip()
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Username and password required'}), 400

    ip_address = request.remote_addr

    if not check_rate_limit(username, ip_address):
        audit_log(None, 'login_blocked', f'Rate limit exceeded for {username}')
        return jsonify({'error': 'Too many attempts. Try again later.'}), 429

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?', (username,)
    ).fetchone()

    if user is None:
        # Prevent user enumeration via timing
        verify_password(password, 'dummy$' + 'a' * 64)
        record_attempt(username, ip_address, False)
        return jsonify({'error': 'Invalid credentials'}), 401

    if not user['is_active']:
        record_attempt(username, ip_address, False)
        return jsonify({'error': 'Account disabled'}), 403

    if not verify_password(password, user['password_hash']):
        record_attempt(username, ip_address, False)
        audit_log(user['id'], 'login_failed', f'From {ip_address}')
        return jsonify({'error': 'Invalid credentials'}), 401

    record_attempt(username, ip_address, True)
    token = create_session(user['id'], ip_address)
    audit_log(user['id'], 'login_success', f'From {ip_address}')

    return jsonify({
        'token': token,
        'expires_in': 3600,
        'user': {'username': user['username'], 'role': user['role']}
    })

@app.route('/api/auth/logout', methods=['POST'])
@require_auth
def logout():
    """Invalidate current session."""
    token = request.headers.get('Authorization', '')[7:]
    db = get_db()
    db.execute('DELETE FROM sessions WHERE token = ?', (token,))
    db.commit()
    audit_log(g.current_user['user_id'], 'logout')
    return jsonify({'message': 'Logged out'})

