@app.route('/api/users/<int:user_id>/role', methods=['PUT'])
@require_auth
@require_role('admin')
def update_role(user_id):
    """Update user role (admin only)."""
    data = request.get_json(force=False, silent=True)
    if not data or 'role' not in data:
        return jsonify({'error': 'Role required'}), 400

    new_role = data['role']
    if new_role not in ('user', 'admin', 'moderator'):
        return jsonify({'error': 'Invalid role'}), 400

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, user_id))
    db.commit()
    audit_log(g.current_user['user_id'], 'role_change',
              f'User {user_id} role changed to {new_role}')
    return jsonify({'message': 'Role updated'})

@app.route('/api/users/search', methods=['GET'])
@require_auth
def search_users():
    """Search users by username pattern."""
    query = request.args.get('q', '').strip()
    if not query or len(query) < 2:
        return jsonify({'error': 'Query too short'}), 400

    # Sanitize search query for LIKE pattern
    sanitized = query.replace('%', '').replace('_', '').replace('\\', '')
    if not sanitized:
        return jsonify({'error': 'Invalid query'}), 400

    db = get_db()
    # Build search with parameterized query
    search_pattern = f"%{sanitized}%"

    # Role-based access: non-admins can only see active users
    if g.current_user['role'] == 'admin':
        users = db.execute(
            'SELECT id, username, role, is_active FROM users WHERE username LIKE ?',
            (search_pattern,)
        ).fetchall()
    else:
        users = db.execute(
            'SELECT id, username, role FROM users WHERE username LIKE ? AND is_active = 1',
            (search_pattern,)
        ).fetchall()

    return jsonify({'users': [dict(u) for u in users]})

