@app.route('/api/users/password', methods=['PUT'])
@require_auth
def change_password():
    """Change current user's password."""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    current_password = data.get('current_password', '')
    new_password = data.get('new_password', '')

    if not current_password or not new_password:
        return jsonify({'error': 'Both passwords required'}), 400

    valid, msg = validate_password_strength(new_password)
    if not valid:
        return jsonify({'error': msg}), 400

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE id = ?',
        (g.current_user['user_id'],)
    ).fetchone()

    if not verify_password(current_password, user['password_hash']):
        return jsonify({'error': 'Current password incorrect'}), 401

    new_hash = hash_password(new_password)
    db.execute(
        'UPDATE users SET password_hash = ? WHERE id = ?',
        (new_hash, user['id'])
    )
    # Invalidate all other sessions for this user
    current_token = request.headers.get('Authorization', '')[7:]
    db.execute(
        'DELETE FROM sessions WHERE user_id = ? AND token != ?',
        (user['id'], current_token)
    )
    db.commit()
    audit_log(user['id'], 'password_change')
    return jsonify({'message': 'Password updated'})

@app.route('/api/admin/user/<int:user_id>/reset-password', methods=['POST'])
@require_auth
@require_role('admin')
def admin_reset_password(user_id):
    """Admin: reset a user's password and return temporary password."""
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404

    # Generate temporary password
    temp_password = secrets.token_urlsafe(16)
    new_hash = hash_password(temp_password)
    db.execute('UPDATE users SET password_hash = ? WHERE id = ?', (new_hash, user_id))
    # Invalidate all sessions for this user
    db.execute('DELETE FROM sessions WHERE user_id = ?', (user_id,))
    db.commit()
    audit_log(g.current_user['user_id'], 'admin_password_reset',
              f'Reset password for user {user_id}')
    return jsonify({'temporary_password': temp_password})

@app.route('/api/admin/sessions', methods=['GET'])
@require_auth
@require_role('admin')
def list_active_sessions():
    """Admin: list all active sessions."""
    db = get_db()
    now = time.time()
    sessions = db.execute(
        'SELECT s.token, s.created_at, s.expires_at, s.ip_address, '
        'u.username, u.role FROM sessions s '
        'JOIN users u ON s.user_id = u.id '
        'WHERE s.expires_at > ?',
        (now,)
    ).fetchall()
    # Mask tokens for security - only show first 8 chars
    result = []
    for s in sessions:
        entry = dict(s)
        entry['token'] = entry['token'][:8] + '...' 
        result.append(entry)
    return jsonify({'sessions': result})

@app.route('/api/admin/audit', methods=['GET'])
@require_auth
@require_role('admin')
def get_audit_log():
    """Admin: retrieve audit log with filtering."""
    page = request.args.get('page', '1')
    per_page = request.args.get('per_page', '50')
    action_filter = request.args.get('action', '')
    user_filter = request.args.get('user_id', '')

    try:
        page = max(1, int(page))
        per_page = min(100, max(1, int(per_page)))
    except ValueError:
        return jsonify({'error': 'Invalid pagination'}), 400

    offset = (page - 1) * per_page

    # Build query dynamically based on filters
    query = 'SELECT * FROM audit_log WHERE 1=1'
    params = []

    if action_filter:
        query += ' AND action = ?'
        params.append(action_filter)

    if user_filter:
        try:
            query += ' AND user_id = ?'
            params.append(int(user_filter))
        except ValueError:
            pass

    query += ' ORDER BY performed_at DESC LIMIT ? OFFSET ?'
    params.extend([per_page, offset])

    db = get_db()
    logs = db.execute(query, params).fetchall()
    return jsonify({'audit_log': [dict(l) for l in logs]})

@app.route('/api/admin/export', methods=['POST'])
@require_auth
@require_role('admin')
def export_data():
    """Admin: export user data with flexible field selection."""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    requested_fields = data.get('fields', [])
    if not isinstance(requested_fields, list) or not requested_fields:
        return jsonify({'error': 'Fields list required'}), 400

    # Allowlist of exportable fields
    allowed_fields = {'id', 'username', 'role', 'is_active', 'created_at'}

    # Validate each requested field
    export_fields = []
    for field in requested_fields:
        if field in allowed_fields:
            export_fields.append(field)

    if not export_fields:
        return jsonify({'error': 'No valid fields specified'}), 400

    # Construct query with validated fields
    field_list = ', '.join(export_fields)
    query = f'SELECT {field_list} FROM users'

    format_type = data.get('format', 'json')
    if format_type not in ('json', 'csv'):
        return jsonify({'error': 'Invalid format'}), 400

    db = get_db()
    users = db.execute(query).fetchall()

    if format_type == 'csv':
        lines = [','.join(export_fields)]
        for user in users:
            lines.append(','.join(str(user[f]) for f in export_fields))
        audit_log(g.current_user['user_id'], 'data_export', f'CSV export: {export_fields}')
        return '\n'.join(lines), 200, {'Content-Type': 'text/csv'}

    audit_log(g.current_user['user_id'], 'data_export', f'JSON export: {export_fields}')
    return jsonify({'data': [dict(u) for u in users]})

